{"code": "import requests, json, time

CAMOFOX = "http://localhost:9377"
USER_ID = "amazon_partnernet"
tab_id = "6dc574fb-7d63-4d9e-a210-572409d4fa3e"

# Try various known partner dashboard URLs
urls = [
    "https://partnernet.amazon.de/gp/associates/network/home.html",
    "https://partnernet.amazon.de/gp/associates/network/reports/report.html",
    "https://partnernet.amazon.de/gp/associates/network/links/list.html",
    "https://partnernet.amazon.de/home",
    "https://partnernet.amazon.de/dashboard",
    "https://partnernet.amazon.de/gp/associates/network/your-account/settings.html",
]

for url in urls:
    print(f"\n🔄 Navigiere zu: {url}")
    resp = requests.post(f"{CAMOFOX}/tabs/{tab_id}/navigate", json={
        "userId": USER_ID, "url": url
    }, timeout=20)
    time.sleep(4)

    # Get URL after redirect
    r = requests.post(f"{CAMOFOX}/tabs/{tab_id}/evaluate", json={
        "userId": USER_ID, "expression": "window.location.href"
    }, timeout=15)
    current_url = r.json().get('result', '')
    print(f"   Final URL: {current_url}")

    # If we're on partnernet and not showing login/denied, check
    if "partnernet" in current_url and "signin" not in current_url and "login" not in current_url:
        snap = requests.get(f"{CAMOFOX}/tabs/{tab_id}/snapshot", params={"userId": USER_ID}, timeout=30)
        s = snap.json().get('snapshot', '')[:800]
        print(f"   Snapshot: {s}")

        if "Access Denied" in s:
            print("   ❌ Access Denied (Session not associated)")
        elif "dashboard" in current_url.lower() or "home" in current_url.lower():
            print("   ✅ Dashboard gefunden!")
            break
        else:
            print("   🔍 Unclear state")
    elif "signin" in current_url.lower():
        print("   ❌ Login-Seite (nicht eingeloggt)")

# Also check: is there perhaps an amazon.de session that's logged in?
requests.post(f"{CAMOFOX}/tabs/{tab_id}/navigate", json={
    "userId": USER_ID, "url": "https://www.amazon.de/"
}, timeout=20)
time.sleep(4)
resp = requests.post(f"{CAMOFOX}/tabs/{tab_id}/evaluate", json={
    "userId": USER_ID, "expression": "window.location.href"
